export function AppNavigator() {
  return (
    <NavigationContainer>
      <Stack.Navigator
        initialRouteName="DesignHomeProtoDefault"
        screenOptions={{ headerShown: false }}
      >
      <Stack.Screen name="DesignHomeProtoDefault" component={DesignHomeProtoDefault} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}

